LOCAL SOURCE EXCERPT, read from filesystem; line numbers preserved.
1: /* ASO patient chat · allowlisted A2UI-shaped surface renderer.
2:    The assistant never sends HTML. It sends messages (createSurface,
3:    updateComponents, updateDataModel) describing a flat list of components
4:    from one catalog, plus a data model the components bind to by path.
5:    Only the components and actions named here render. Anything else, and
6:    in particular any affirmation, signing or submission control, is refused
7:    in place: those belong to the host (see host-controls.js). */
8: (function (g) {
9:   'use strict';
10:   var ASO = g.ASO = g.ASO || {};
11:   var h = ASO.h;
12:   var CATALOG = 'aso.workbench/v1';
13:   var ACTIONS = { answer_question: 1, send_staff_request: 1, open_source: 1, set_context: 1, run_prompt: 1 };
64:   C.Column = function (s, c) { return h('div', { class: 'a-col' }, kids(s, c)); };
65:   C.Row = function (s, c) { return h('div', { class: 'a-row' }, kids(s, c)); };
66:   C.Section = function (s, c) {
67:     return h('section', { class: 'a-sec' }, [h('h3', { class: 'a-sec-h', text: c.title })].concat(kids(s, c)));
68:   };
69:   C.Text = function (s, c) {
70:     var t = val(s, c.text);
71:     return h('p', { class: 'a-text a-' + (c.variant || 'body'), text: t == null ? '' : String(t) });
72:   };
73:   C.Citation = function (s, c) { return cite(s, val(s, c.doc), val(s, c.page), c.fallback); };
74:   C.Button = function (s, c) { return actionButton(s, c.action, c.variant); };
75: 
76:   C.CaseHeader = function (s, c) {
77:     var v = val(s, c.value) || {};
78:     var rows = [['Patient', v.patient], ['Case', v.id], ['Procedure', v.procedure], ['Codes', v.codes],
79:       ['Payer', v.payer], ['Policy', v.policy], ['Status', v.status]];
80:     return h('dl', { class: 'a-facts' }, rows.filter(function (r) { return !!r[1]; }).map(function (r) {
81:       return h('div', { class: 'a-fact' }, [h('dt', { text: r[0] }), h('dd', { text: r[1] })]);
82:     }));
83:   };
84: 
85:   C.CriteriaList = function (s, c) {
86:     var items = val(s, c.items) || [];
87:     if (!items.length) return h('p', { class: 'a-empty', text: 'No policy criteria are matched to this case yet.' });
88:     return h('ul', { class: 'a-crit' }, items.map(function (k) {
89:       var list = k.cites && k.cites.length ? k.cites : [{ doc: k.doc, page: k.page }];
90:       return h('li', { class: 'a-crit-row' }, [
91:         h('div', null, ASO.stateChip(k.state)),
92:         h('div', { class: 'od-field od-fill' }, [
93:           h('span', { class: 'a-crit-name' }, [h('span', { class: 'sec od-nowrap', text: k.sec }), ' ', k.name]),
94:           h('span', { class: 'a-crit-ev', text: k.evidence }),
95:           h('span', { class: 'a-cites od-cluster' }, list.map(function (x) { return cite(s, x.doc, x.page, k.cite); }))
96:         ])
97:       ]);
98:     }));
99:   };
100: 
101:   C.ConflictList = function (s, c) {
102:     var items = val(s, c.items) || [];
103:     if (!items.length) return h('p', { class: 'a-empty', text: 'None on file.' });
104:     return h('ul', { class: 'a-list' }, items.map(function (x) {
105:       return h('li', { class: 'a-item' }, [
106:         h('span', { class: 'a-item-h od-cluster' }, [
107:           h('span', { class: 'a-kind', text: x.kind }),
108:           h('span', { class: 'a-owner', text: x.resolved ? 'Clarified by surgeon' : 'Open' })
109:         ]),
110:         h('span', { class: 'a-item-t', text: x.text }),
111:         x.statement ? h('span', { class: 'a-stmt', text: 'Surgeon statement: ' + x.statement }) : null,
112:         h('span', { class: 'a-cites od-cluster' }, [cite(s, x.doc, x.page)])
113:       ]);
114:     }));
115:   };
116: 
117:   C.BlockerList = function (s, c) {
118:     var items = val(s, c.items) || [];
119:     if (!items.length) return h('p', { class: 'a-empty', text: 'No open blockers.' });
120:     return h('ul', { class: 'a-list' }, items.map(function (b) {
121:       return h('li', { class: 'a-item' }, [
122:         h('span', { class: 'a-item-t', text: b.text }),
123:         h('span', { class: 'a-item-h od-cluster' }, [h('span', { class: 'a-owner', text: b.owner })])
124:       ]);
125:     }));
126:   };
127: 
128:   C.NextMove = function (s, c) {
129:     var action = c.action ? h('div', { class: 'a-actions od-cluster' }, [actionButton(s, c.action)]) : null;
130:     return h('div', { class: 'a-item' }, [h('p', { class: 'a-next', text: String(val(s, c.text) || '') }), action]);
131:   };
132: 
133:   /* The coach asks one question at a time and records the answer as the
134:      surgeon's own statement. Once answered, the surface locks. */
135:   C.ChoiceQuestion = function (s, c) {
136:     var ans = val(s, c.answer);
